from dataclasses import dataclass, field
from enum import Enum

class BankError(Exception):
    """Base class for every bank rule violation."""


class InvalidAmountError(BankError):
    pass


class InsufficientFundsError(BankError):
    def __init__(self, balance, requested):
        super().__init__(f"balance {balance}, requested {requested}")
        self.balance = balance
        self.requested = requested


class Kind(Enum):
    DEPOSIT = "deposit"
    WITHDRAW = "withdraw"


@dataclass(frozen=True)
class Transaction:
    kind: Kind
    amount: int
    balance_after: int


def check_amount(amount):
    if not isinstance(amount, int) or amount <= 0:
        raise InvalidAmountError(f"amount must be a positive whole number, got {amount!r}")


@dataclass
class Account:
    number: str
    owner: str
    balance: int = 0
    history: list[Transaction] = field(default_factory=list)

    def deposit(self, amount: int) -> None:
        check_amount(amount)
        self.balance += amount
        self.history.append(Transaction(Kind.DEPOSIT, amount, self.balance))

    def withdraw(self, amount: int) -> None:
        check_amount(amount)
        if amount > self.balance:
            raise InsufficientFundsError(self.balance, amount)
        self.balance -= amount
        self.history.append(Transaction(Kind.WITHDRAW, amount, self.balance))


acct = Account("AC1001", "Riya")
acct.deposit(5000)
acct.withdraw(1200)
print(acct.balance, len(acct.history))

slides.tests:
acct_t = Account("AC1", "Riya")
acct_t.deposit(5000)
assert acct_t.balance == 5000, f"After depositing 5000 the balance should be 5000, got {acct_t.balance}."
assert acct_t.history == [Transaction(Kind.DEPOSIT, 5000, 5000)], f"Record Transaction(Kind.DEPOSIT, 5000, 5000), got {acct_t.history}."
acct_t.withdraw(1200)
assert acct_t.balance == 3800, f"5000 - 1200 = 3800, got {acct_t.balance}."
assert acct_t.history[-1] == Transaction(Kind.WITHDRAW, 1200, 3800), f"Record Transaction(Kind.WITHDRAW, 1200, 3800), got {acct_t.history[-1]}."
try:
    acct_t.withdraw(10000)
except InsufficientFundsError as e:
    assert (e.balance, e.requested) == (3800, 10000), "Raise InsufficientFundsError(self.balance, amount)."
else:
    raise AssertionError("Withdrawing 10000 from 3800 should raise InsufficientFundsError.")
assert acct_t.balance == 3800 and len(acct_t.history) == 2, "A refused withdrawal must change nothing: same balance, no new transaction."
for bad in (0, -50, 10.5):
    for name in ("deposit", "withdraw"):
        try:
            getattr(acct_t, name)(bad)
        except InvalidAmountError:
            pass
        else:
            raise AssertionError(f"{name}({bad!r}) should raise InvalidAmountError: amounts must be positive whole rupees.")
assert acct_t.balance == 3800 and len(acct_t.history) == 2, "Rejected amounts must not change the balance or the history."
full = Account("AC2", "Arjun", balance=100)
full.withdraw(100)
assert full.balance == 0, "Withdrawing exactly the whole balance is allowed and leaves 0."

